mapper.select:
select 
from wallet_journal
where owner_id = #{ownerId} and division = #{division}
and user_id = #{userId}
order by `date` desc

select
  COALESCE(SUM(CASE WHEN w.amount > 0 THEN w.amount ELSE 0 END), 0)  as totalIncome,
  COALESCE(SUM(CASE WHEN w.amount < 0 THEN -w.amount ELSE 0 END), 0) as totalExpense,
  COALESCE(SUM(w.amount), 0)                                            as netFlow,
  COUNT(*)                                                              as journalCount,
  (select w2.balance from wallet_journal w2
    where w2.owner_id = #{ownerId}
    and w2.division = #{division}
    and w2.user_id = #{userId}
    order by w2.id desc limit 1)                                        as currentBalance,
  (select MAX(w3.`date`) from wallet_journal w3
    where w3.owner_id = #{ownerId}
    and w3.division = #{division}
    and w3.user_id = #{userId})    as asOfTime
from wallet_journal w
where w.owner_id = #{ownerId}
and w.division = #{division}
and w.user_id = #{userId}
and w.`date` >= #{start}
and w.`date` <= #{end}

select
  w.ref_type                                                        as refType,
  COALESCE(SUM(CASE WHEN w.amount > 0 THEN w.amount ELSE 0 END), 0) as income,
  COALESCE(SUM(CASE WHEN w.amount < 0 THEN -w.amount ELSE 0 END), 0) as expense,
  COUNT(*)                                                          as count
from wallet_journal w
where w.owner_id = #{ownerId}
and w.division = #{division}
and w.user_id = #{userId}
and w.`date` >= #{start}
and w.`date` <= #{end}
group by w.ref_type
order by (income + expense) desc
limit 50

select
  DATE_FORMAT(w.`date`, #{granularity})                             as bucket,
  COALESCE(SUM(CASE WHEN w.amount > 0 THEN w.amount ELSE 0 END), 0) as income,
  COALESCE(SUM(CASE WHEN w.amount < 0 THEN -w.amount ELSE 0 END), 0) as expense,
  SUM(w.amount)                                                     as net
from wallet_journal w
where w.owner_id = #{ownerId}
and w.division = #{division}
and w.user_id = #{userId}
and w.`date` >= #{start}
and w.`date` <= #{end}
group by bucket
order by bucket asc

select
  division,
  0.0 as balance,
  COALESCE(SUM(CASE WHEN amount > 0 THEN amount ELSE 0 END), 0) as income,
  COALESCE(SUM(CASE WHEN amount < 0 THEN -amount ELSE 0 END), 0) as expense
from wallet_journal
where owner_id = #{ownerId}
and user_id = #{userId}
and `date` >= #{start}
and `date` <= #{end}
group by division
